import re

def word_freq(text):
    if not text:
        return {}

    # Extract words (maximal runs of ASCII letters) and convert to lowercase
    words = re.findall(r'[A-Za-z]+', text.lower())

    # Count frequency of each word
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1

    return freq
