def longest_uniform_run(bits, k):
    if not bits:
        return 0

    left = 0
    max_length = 0
    zeros_count = 0
    ones_count = 0

    for right in range(len(bits)):
        if bits[right] == 0:
            zeros_count += 1
        else:
            ones_count += 1

        # Shrink window if we exceed k flips
        while zeros_count > k and ones_count > k:
            if bits[left] == 0:
                zeros_count -= 1
            else:
                ones_count -= 1
            left += 1

        # Update max_length with the current window size
        # The maximum uniform run we can achieve is limited by the smaller count
        # since we can flip the minority to match the majority
        max_length = max(max_length, right - left + 1)

    return max_length
