def longest_uniform_run(bits, k):
    def max_run_for(value):
        opposite = 0
        left = 0
        best = 0

        for right, bit in enumerate(bits):
            if bit != value:
                opposite += 1

            while opposite > k:
                if bits[left] != value:
                    opposite -= 1
                left += 1

            best = max(best, right - left + 1)

        return best

    if not bits:
        return 0

    return max(max_run_for(0), max_run_for(1))
```

