def merge_intervals(intervals):
    intervals = [[a, b] for a, b in intervals if a < b]
    intervals.sort(key=lambda x: (x[0], x[1]))

    merged = []
    for a, b in intervals:
        if not merged or a >= merged[-1][1]:
            merged.append([a, b])
        else:
            if b > merged[-1][1]:
                merged[-1][1] = b

    return merged
