def eval_expr(s):
    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i].isdigit():
                num = 0
                while i < len(expr) and expr[i].isdigit():
                    num = num * 10 + int(expr[i])
                    i += 1
                tokens.append(num)
                continue
            if expr[i] in '+-*/^()':
                tokens.append(expr[i])
            else:
                return None  # invalid character
            i += 1
        return tokens

    def parse_expr(tokens, pos):
        result, pos = parse_term(tokens, pos)
        while pos < len(tokens) and tokens[pos] in '+-':
            op = tokens[pos]
            pos += 1
            right, pos = parse_term(tokens, pos)
            if op == '+':
                result += right
            else:
                result -= right
        return result, pos

    def parse_term(tokens, pos):
        result, pos = parse_power(tokens, pos)
        while pos < len(tokens) and tokens[pos] in '*/':
            op = tokens[pos]
            pos += 1
            right, pos = parse_power(tokens, pos)
            if op == '*':
                result *= right
            else:
                if right == 0:
                    return None, len(tokens)
                # Floor division toward negative infinity
                if result >= 0:
                    result //= right
                else:
                    # For negative numbers, adjust to truncate toward -inf
                    result = -(-result // right)
        return result, pos

    def parse_power(tokens, pos):
        result, pos = parse_factor(tokens, pos)
        if pos < len(tokens) and tokens[pos] == '^':
            pos += 1
            right, pos = parse_power(tokens, pos)
            if right < 0:
                return None, len(tokens)
            if result == 0 and right == 0:
                return None, len(tokens)
            result = result ** right
        return result, pos

    def parse_factor(tokens, pos):
        if pos >= len(tokens):
            return None, pos
        if tokens[pos] == '-':
            pos += 1
            val, pos = parse_factor(tokens, pos)
            if val is None:
                return None, pos
            return -val, pos
        elif tokens[pos] == '(':
            pos += 1
            val, pos = parse_expr(tokens, pos)
            if pos >= len(tokens) or tokens[pos] != ')':
                return None, len(tokens)
            pos += 1
            return val, pos
        elif isinstance(tokens[pos], int):
            return tokens[pos], pos + 1
        else:
            return None, pos

    tokens = tokenize(s)
    if tokens is None:
        return None
    result, pos = parse_expr(tokens, 0)
    if result is None or pos != len(tokens):
        return None
    return result
