def solve_cryptarithm(puzzle):
    # Parse the puzzle
    puzzle = puzzle.replace(' ', '')
    parts = puzzle.split('=')
    if len(parts) != 2:
        return None
    left_side = parts[0]
    right_side = parts[1]

    addends = left_side.split('+')

    # Collect all letters and identify leading letters
    letters = set()
    leading_letters = set()

    for word in addends + [right_side]:
        if len(word) > 0:
            letters.update(word)
            leading_letters.add(word[0])

    # If more than 10 distinct letters, no solution possible
    if len(letters) > 10:
        return None

    # Convert to list for consistent ordering
    letter_list = list(letters)

    # Try all permutations of digits for the letters
    from itertools import permutations

    # We'll use a recursive backtracking approach with pruning
    def backtrack(index, digit_map, used_digits, current_sum):
        if index == len(letter_list):
            # Check if the equation holds
            left_sum = 0
            for word in addends:
                num = 0
                for c in word:
                    num = num * 10 + digit_map[c]
                left_sum += num
            right_num = 0
            for c in right_side:
                right_num = right_num * 10 + digit_map[c]
            return left_sum == right_num

        letter = letter_list[index]
        start_digit = 0 if letter not in leading_letters else 1

        for d in range(start_digit, 10):
            if d not in used_digits:
                digit_map[letter] = d
                used_digits.add(d)

                if backtrack(index + 1, digit_map, used_digits, current_sum):
                    return True

                used_digits.remove(d)
                del digit_map[letter]

        return False

    # Try to find a solution
    digit_map = {}
    used_digits = set()

    # We'll use a different approach: try all permutations of digits for the letters
    # But only if we have at most 10 letters
    solutions = []

    for perm in permutations(range(10), len(letter_list)):
        # Create mapping
        digit_map = {letter_list[i]: perm[i] for i in range(len(letter_list))}

        # Check leading zeros
        valid = True
        for letter in leading_letters:
            if digit_map[letter] == 0:
                valid = False
                break
        if not valid:
            continue

        # Check if equation holds
        left_sum = 0
        for word in addends:
            num = 0
            for c in word:
                num = num * 10 + digit_map[c]
            left_sum += num

        right_num = 0
        for c in right_side:
            right_num = right_num * 10 + digit_map[c]

        if left_sum == right_num:
            solutions.append(digit_map.copy())
            if len(solutions) > 1:
                return None  # More than one solution

    if len(solutions) == 1:
        return solutions[0]
    else:
        return None
