def roman_to_int(s):
    if not s:
        return None

    # Define valid symbols and their values
    roman_values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check for invalid characters
    for char in s:
        if char not in roman_values:
            return None

    # Check for repeated V, L, D
    for char in ['V', 'L', 'D']:
        if char in s:
            if s.count(char) > 1:
                return None

    # Check for more than 3 consecutive I, X, C, M
    for char in ['I', 'X', 'C', 'M']:
        if char * 4 in s:
            return None

    # Check for valid subtractive pairs and their positions
    subtractive_pairs = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}
    for pair in subtractive_pairs:
        if pair in s:
            # Ensure pair appears only once
            if s.count(pair) > 1:
                return None
            # Ensure pair is not adjacent to another valid pair
            # Check if pair is followed by a valid symbol that could form another pair
            for i in range(len(s) - 1):
                if s[i:i+2] == pair:
                    # Check if this pair is followed by a symbol that could form another subtractive pair
                    if i + 2 < len(s):
                        next_char = s[i+2]
                        if next_char in ['V', 'L', 'D', 'M']:
                            # Check if next_char is part of a valid pair
                            if i + 3 < len(s) and s[i+2:i+4] in subtractive_pairs:
                                return None
                    # Check if this pair is preceded by a symbol that could form another subtractive pair
                    if i > 0:
                        prev_char = s[i-1]
                        if prev_char in ['I', 'X', 'C', 'M']:
                            if i - 1 > 0 and s[i-2:i] in subtractive_pairs:
                                return None
        else:
            # If pair is not present, ensure it's not used in a non-canonical way
            # e.g., "IV" is valid, but "VI" is not a subtractive pair
            pass

    # Check for invalid sequences like "IC", "ID", "IM", "XD", "XM"
    invalid_subtractive = ['IC', 'ID', 'IM', 'XD', 'XM']
    for invalid in invalid_subtractive:
        if invalid in s:
            return None

    # Check for invalid sequences like "VX", "VV", "LL", "DD", "MM" (but MM is valid)
    invalid_sequences = ['VX', 'VV', 'LL', 'DD']
    for invalid in invalid_sequences:
        if invalid in s:
            return None

    # Validate the string by building it step by step
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in subtractive_pairs:
            total += subtractive_pairs[s[i:i+2]]
            i += 2
        elif s[i] in roman_values:
            total += roman_values[s[i]]
            i += 1
        else:
            return None

    # Final check: ensure the constructed value is within range and matches the canonical form
    # Reconstruct the canonical form and compare
    def int_to_roman(num):
        if num <= 0 or num > 3999:
            return None
        values = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
        ]
        result = ""
        for value, symbol in values:
            count = num // value
            result += symbol * count
            num -= value * count
        return result

    canonical = int_to_roman(total)
    if canonical != s:
        return None

    return total
