def longest_uniform_run(bits, k):
    if not bits:
        return 0
    n = len(bits)
    best = 0
    for target in (0, 1):
        left = 0
        opposite = 0
        for right in range(n):
            if bits[right] != target:
                opposite += 1
            while opposite > k:
                if bits[left] != target:
                    opposite -= 1
                left += 1
            best = max(best, right - left + 1)
    return best
